SELECT count(*) FROM schools JOIN frpm ON schools.CDSCode = frpm.CDSCode WHERE schools.Magnet = 1 AND schools.GSserved = 'K-8' AND frpm."NSLP Provision Status" = 'Multiple Provision Types';
SELECT count(DISTINCT City) FROM schools WHERE GSserved = 'K-8';
SELECT City, count(*) FROM schools WHERE GSserved = 'K-8' GROUP BY City;
